import type { KeyRow } from '../services/router.js';

/**
 * Manages a pool of API keys for a single provider with automatic cooldown on rate limit errors.
 */
export class KeyPoolManager {
  private provider: string;
  private keys: KeyRow[]; // all keys for this provider (enabled, healthy/unknown)
  private keyCooldowns: Map<number, number>; // keyId -> expiry timestamp (ms)
  private roundRobinIndex: number;

  constructor(provider: string, keys: KeyRow[]) {
    this.provider = provider;
    this.keys = keys.filter(k => k.enabled === 1 && k.status === 'healthy' || k.status === 'unknown');
    this.keyCooldowns = new Map();
    this.roundRobinIndex = 0;
  }

  /**
   * Acquires the next available key using round-robin, skipping keys in cooldown.
   * Returns null if no key is available.
   */
  acquireKey(): KeyRow | null {
    if (this.keys.length === 0) return null;

    const startIndex = this.roundRobinIndex;
    let attempts = 0;
    while (attempts < this.keys.length) {
      const key = this.keys[this.roundRobinIndex];
      this.roundRobinIndex = (this.roundRobinIndex + 1) % this.keys.length;
      attempts++;

      const keyId = key.id;
      const expiry = this.keyCooldowns.get(keyId);
      const now = Date.now();

      if (!expiry || expiry <= now) {
        // Key is available
        return key;
      }
      // Key is in cooldown, try next
    }
    // No available key after a full cycle
    return null;
  }

  /**
   * Marks a key as failed (e.g., due to 429/402) and puts it in cooldown.
   * @param keyId The ID of the key that failed
   * @param errorStatus The HTTP error status (e.g., 429, 402, 500)
   */
  markKeyFailed(keyId: number, errorStatus: number): void {
    let baseCooldownMs = 30 * 1000; // 30 seconds base
    // In future, we can adjust baseCooldownMs based on error type or model cost
    // For now, use fixed cooldown for 429/402, shorter for other errors?
    if (errorStatus === 429 || errorStatus === 402) {
      // Base cooldown
    } else {
      // For other errors (5xx, timeout), use shorter cooldown
      baseCooldownMs = 10 * 1000; // 10 seconds
    }
    const expiry = Date.now() + baseCooldownMs;
    this.keyCooldowns.set(keyId, expiry);
    // TODO: Telemetry log cooldown start
  }

  /**
   * Releases a key after successful use (resets any cooldown?).
   * Actually, we don't reset cooldown on success; we only remove on cooldown expiry.
   * But we can clear any failure count if we were tracking it.
   * For now, we do nothing on success.
   */
  releaseKey(keyId: number): void {
    // Optionally, we could reduce cooldown on success, but not required.
    // TODO: Telemetry log key release
  }

  /**
   * Checks if a key is currently available (not in cooldown).
   */
  isKeyAvailable(keyId: number): boolean {
    const expiry = this.keyCooldowns.get(keyId);
    if (!expiry) return true;
    return expiry <= Date.now();
  }

  /**
   * Refreshes the key list from the database (call periodically or on demand).
   * This should be called when the set of keys for a provider might have changed.
   */
  async refreshKeys(): Promise<void> {
    const db = getDb();
    const rows = db.prepare(
      `SELECT * FROM api_keys WHERE platform = ? AND enabled = 1 AND status IN ('healthy', 'unknown')`
    ).all(this.provider) as KeyRow[];
    this.keys = rows;
    // Note: we do not reset roundRobinIndex or cooldowns on refresh to avoid starvation.
  }
}"}

