import type { KeyRow } from '../services/router.js';

/**
 * Manages a pool of API keys for a single provider with automatic cooldown on rate limit errors.
 */
export class KeyPoolManager {
  private provider: string;
  private keys: KeyRow[]; // all keys for this provider (enabled, healthy/unknown)
  private keyCooldowns: Map<number, number>; // keyId -> expiry timestamp (ms)
  private roundRobinIndex: number;
  private lastRefresh: number;
  private static readonly REFRESH_INTERVAL_MS = 5 * 60 * 1000; // 5 minutes

  // Base cooldown in milliseconds for rate limit errors (429/402)
  private static readonly BASE_COOLDOWN_MS = 30 * 1000; // 30 seconds
  // Base cooldown for other errors (5xx, timeout)
  private static readonly BASE_COOLDOWN_MS_OTHER = 10 * 1000; // 10 seconds

  // Cost multipliers for providers (higher cost -> longer cooldown to give free models more chances)
  private static readonly PROVIDER_COST_MULTIPLIER: Record<string, number> = {
    // Free or low-cost providers
    ollama: 0.5, // local models, consider free
    // Add more as needed
    // Default multiplier for unknown providers
  };

  constructor(provider: string, keys: KeyRow[]) {
    this.provider = provider;
    this.keys = keys.filter(k => k.enabled === 1 && k.status === 'healthy' || k.status === 'unknown');
    this.keyCooldowns = new Map();
    this.roundRobinIndex = 0;
    this.lastRefresh = Date.now();
  }

  /**
   * Acquires the next available key using round-robin, skipping keys in cooldown.
   * Returns null if no key is available.
   */
  acquireKey(): KeyRow | null {
    this.maybeRefreshKeys();
    if (this.keys.length === 0) return null;

    const startIndex = this.roundRobinIndex;
    let attempts = 0;
    while (attempts < this.keys.length) {
      const key = this.keys[this.roundRobinIndex];
      this.roundRobinIndex = (this.roundRobinIndex + 1) % this.keys.length;
      attempts++;

      const keyId = key.id;
      const expiry = this.keyCooldowns.get(keyId);
