export function routeRequest(
  estimatedTokens: number | null | undefined,
  skipKeys?: Set<string> | undefined,
  preferredModelDbId: number | null | undefined,
  requireVision: boolean = false,
  requireTools: boolean = false,
  skipPlatforms?: Set<string> | undefined
