function getCustomWeights(): RoutingWeights {
  const db = getDb();
  const reliability = getSetting('custom_weight_reliability') ?? 0.33;
  const speed = getSetting('custom_weight_speed') ?? 0.33;
  const intelligence = getSetting('custom_weight_intelligence') ?? 0.34;

  // Normalize to sum 1
  const total = reliability + speed + intelligence;
  return {
    reliability: reliability / total,
    speed: speed / total,
    intelligence: intelligence / total
