  return `~${Math.round(mins / 60)}h`;
}

const EXHAUSTION_ADVICE = 'Add more API keys or wait for rate limits to reset.';

// Roll the per-model diagnostics (see RouteError.diagnostics) up into a short,
// client-safe summary so an exhausted caller learns WHY the pool was empty
// instead of a bare "All models exhausted" (#423). Buckets are aggregate
// counts only — no key material, no per-key detail. Classifies off the whole
// line (model ids can contain ':' so splitting label from reason is unsafe).
export function summarizeExhaustion(
  diagnostics: string[] | undefined,
  i18nPrefix: string = 'routing_error'
): string {
  if (!diagnostics || diagnostics.length === 0) {
    return `${i18nPrefix}.all_exhausted`;
  }
  const counts: Record<string, number> = {};
  for (const diag of diagnostics) {
    const [reason, countStr] = diag.split(':');
    const count = parseInt(countStr, 10);
    if (!isNaN(count)) {
      counts[reason] = (counts[reason] ?? 0) + count;
    }
  }
  // Sort by count descending, then alphabetically by reason for deterministic output
  const sorted = Object.entries(counts)
    .sort(([, a], [, b]) => b - a || a.localeCompare(b))
    .map(([reason, count]) => `${reason}:${count}`);
  return `${i18nPrefix}.${sorted.join('_')}`;
}

// How many tokens to reserve for the routing system itself (e.g., for fallback
// loops, retries, etc.) so we don't accidentally exceed the model's context window.
export function routingReserveTokens(requestedMaxTokens: number | null | undefined): number {
  if (requestedMaxTokens === null) return 0;
  // Reserve 10% of the requested max tokens, but at least 100 and at most 1000.
  const reserve = Math.max(100, Math.min(1000, Math.floor(requestedMaxTokens * 0.1)));
  return reserve;
}

// Records a model-level failure (e.g., all keys exhausted) for the bandit.
// The weight is how much to penalize the model's score (higher = worse).
export function recordModelFailure(modelDbId: number, weight = PENALTY_PER_FAIL): void {
  const db = getDb();
  db.prepare(
    "UPDATE model_stats SET failures = failures + 1, weight = weight + ? WHERE model_db_id = ?"
  ).run(weight, modelDbId);
}

// Records that a rate limit was hit for a specific model/key combo.
// Used by the bandit to adjust the reliability score.
export function recordRateLimitHit(modelDbId: number): void {
  const db = getDb();
  db.prepare(
    "UPDATE model_stats SET rate_limit_hits = rate_limit_hits + 1 WHERE model_db_id = ?"
  ).run(modelDbId);
}

// Whether at least one model in the chain supports vision input.
export function hasEnabledVisionModel(): boolean {
  const db = getDb();
  return getActiveChain(db).some(entry => entry.enabled === 1 && entry.supports_vision === 1);
}

// Whether at least one tool-capable model is enabled in the fallback chain.
// Same role as hasEnabledVisionModel: a clear up-front error for tool-bearing
// requests beats routing them to a model that mangles the tool call.
export function hasEnabledToolsModel(): boolean {
  const db = getDb();
  return getActiveChain(db).some(entry => entry.enabled === 1 && entry.supports_tools === 1);
}

/**
 * Pick a usable key for ONE model and build its RouteResult, or return null if
 * the model has no key that can serve the request right now (all cooled down,
 * over quota, undecryptable, or no provider). Factored out of routeRequest so
 * the fusion panel can HARD-PIN a model: walk that model's keys without ever
 * falling through to a different model (issue #326 — soft preference collapses
 * panel diversity under rate limits). Keys are tried in per-key bandit-score
 * order when any of them has recorded data (#580), else round-robin.
 * Request-level filters (vision/tools/context window) stay in the caller; this
 * only does key selection + accounting pre-checks.
 * 
 * Now uses KeyPoolManager for key rotation and cooldown management on 429/402 errors.
 */
function selectKeyForModel(entry: ChainRow, estimatedTokens: number, skipKeys?: Set<string>, diag?: string[]): RouteResult | null {
  const db = getDb();
  const label = `${entry.platform}/${entry.model_id}`;

  if (!hasProvider(entry.platform as Platform)) {
    diag?.push(`${label}: no provider registered`);
    return null;
  }
  const provider = getProvider(entry.platform as Platform)!;

  // Get all enabled keys for this provider
  const allKeys = db.prepare(
    "SELECT * FROM api_keys WHERE platform = ? AND enabled = 1 AND status IN ('healthy', 'unknown')"
  ).all(entry.platform) as KeyRow[];
  if (allKeys.length === 0) {
    diag?.push(`${label}: no enabled+healthy key for platform`);
    return null;
  }

  // Filter by model scope (scoped keys)
  const keys = allKeys.filter(k => scopeAllows(parseModelScope(k.model_scope_json), entry.model_id));
  if (keys.length === 0) {
    diag?.push(`${label}: no usable key — ${allKeys.length} key(s) scoped to other models`);
    return null;
  }

  // For custom models, restrict to keys belonging to the model's endpoint
  const endpointKeyIds = entry.platform === 'custom' && entry.key_id != null
    ? customEndpointKeyIds(db, entry.key_id)
    : null;
  if (endpointKeyIds) {
    const filteredKeys = keys.filter(k => endpointKeyIds.has(k.id));
    if (filteredKeys.length === 0) {
      diag?.push(`${label}: no usable key — ${keys.length} key(s) not bound to model's endpoint`);
      return null;
    }
    keys = filteredKeys;
  }

  // Refresh stats cache for scoring (if not using priority strategy)
  if (getRoutingStrategy() !== 'priority') {
    refreshStatsCache(db);
  }

  // Get keys in score order (reliability/speed/intelligence)
  let orderedKeys: KeyRow[] | null = orderKeysByScore(entry, keys);
  if (orderedKeys === null) {
    // Fallback to original order if no scoring data
    orderedKeys = keys;
  }

  // Apply remaining-quota weighting if applicable
  if (keys.length > 1 && quotaWeightingApplies(entry)) {
    const rrKey = modelStatsKey(entry.platform, entry.model_id, entry.endpoint_scope);
    const idx = roundRobinIndex.get(rrKey) ?? 0;
    const base = orderedKeys ?? Array.from({ length: keys.length }, (_, i) => keys[(idx + i) % keys.length]);
    orderedKeys = orderKeysByRemainingQuota(entry, base);
  }

  // Filter to only keys available in our KeyPoolManager (not in our 429/402 cooldown)
  const keyPool = KeyPoolManager.getInstance(provider);
  const availableKeys = orderedKeys.filter(key => keyPool.isKeyAvailable(key.id));
  if (availableKeys.length === 0) {
    diag?.push(`${label}: ${keys.length} key(s) — all in cooldown`);
    return null;
  }

  // Tally the gate that rejected each key, so the exhaustion diagnostic can say
  // *why* a model with keys still couldn't serve (all on cooldown vs over quota).
  const skipTally: Record<string, number> = {};
  const note = (reason: string) => { skipTally[reason] = (skipTally[reason] ?? 0) + 1; };

  const limits = {
    rpm: entry.rpm_limit,
    rpd: entry.rpd_limit,
    tpm: entry.tpm_limit,
    tpd: entry.tpd_limit,
  };

  // Try each available key in score/order
  for (const key of availableKeys) {
    const keyId = key.id;
    const skipId = `${entry.platform}:${entry.model_id}:${key.id}`;

    // Skip if this key was already tried and failed in this request
    if (skipKeys?.has(skipId)) { note('already-failed-this-request'); continue; }

    // For custom models, ensure the key belongs to the correct endpoint
    if (endpointKeyIds && !endpointKeyIds.has(key.id)) { note('custom-key-mismatch'); continue; }

    // Check the existing cooldown from ratelimit (isOnCooldown)
    if (isOnCooldown(entry.platform, entry.model_id, key.id)) { note('cooldown'); continue; }
    if (!canUseProvider(entry.platform, key.id)) { note('provider-daily-cap'); continue; }
    // Account-wide per-minute budget
    if (!canUseProviderMinute(entry.platform, key.id)) { note('provider-minute-cap'); continue; }
    // Concurrency limit
    if (!canUseKeyConcurrency(entry.platform, key.id)) { note('key-concurrency'); continue; }
    // Per-model request limits
    if (!canMakeRequest(entry.platform, entry.model_id, key.id, limits)) { note('rpm/rpd-limit'); continue; }
    // Per-model token limits
    if (!canUseTokens(entry.platform, entry.model_id, key.id, estimatedTokens, limits)) { note('tpm/tpd-limit'); continue; }
    // Provider daily token cap
    if (!canUseProviderTokens(entry.platform, key.id, entry.model_id, estimatedTokens)) { note('provider-daily-token-cap'); continue; }

    let decryptedKey: string;
    try {
      decryptedKey = decrypt(key.encrypted_key, key.iv, key.auth_tag);
    } catch {
      db.prepare("UPDATE api_keys SET status = 'error', last_checked_at = datetime('now') WHERE id = ?")
        .run(key.id);
      note('decrypt-error');
      continue;
    }

    const resolvedProvider = entry.platform === 'custom'
      ? resolveProvider('custom', key.base_url)
      : provider;
    if (!resolvedProvider) { note('no-resolved-provider'); continue; }

    // Acquire lease for the actual request attempt
    const leaseId = acquireLease(entry.platform, entry.model_id, key.id, estimatedTokens);
    return {
      provider: resolvedProvider,
      modelId: entry.model_id,
      modelDbId: entry.model_db_id,
      apiKey: decryptedKey,
      keyId: key.id,
      keyLabel: key.label || null,
      // Decrypted once here, at the point the row is already in hand (#590).
      proxyUrl: decryptProxyUrl(key),
      platform: entry.platform,
      displayName: entry.display_name,
      endpointScope: entry.endpoint_scope ?? '',
      rpdLimit: limits.rpd,
      tpdLimit: limits.tpd,
      release: () => releaseLease(leaseId);
    };
  }

  // If we exit the loop, we couldn't find a usable key after checking all available keys.
  const summary = Object.entries(skipTally).map(([r, n]) => `${r}:${n}`).join(', ') || 'no usable key';
  diag?.push(`${label}: ${keys.length} key(s) — ${summary}`);
  return null;
}

/**
 * Whether the model still has ANOTHER key that could serve it right now, given
 * the key that just failed (excludingKeyId) and any keys already ruled out this
 * request (skipKeys, in the "platform:modelId:keyId" form). Applies the same
 * gates selectKeyForModel uses — enabled + healthy status, not on cooldown,
 * under the provider daily cap, and under rpm/rpd/tpm/tpd — so the answer means
 * "a real, dispatchable alternative exists".
 *
 * Used by the retry loops to decide whether a single key's 429 should demote the
 * WHOLE model (the model-level 429 penalty). It should not: the per-key cooldown
 * already isolates the failing key, so demoting the model while a sibling key can
 * still serve it wrongly sinks a healthy model in the scorer (#454). We only
 * record the model-level hit when this returns false — i.e. the 429 exhausted the
 * model, not just one of its keys.
 */
export function hasOtherUsableKey(modelDbId: number, excludingKeyId: number, skipKeys?: Set<string>): boolean {
  const db = getDb();
  const m = db.prepare(`
    SELECT platform, model_id, rpm_limit, rpd_limit, tpm_limit, tpd_limit, key_id
      FROM models WHERE id = ?
  `).get(modelDbId) as {
    platform: string; model_id: string;
    rpm_limit: number | null; rpd_limit: number | null;
    tpm_limit: number | null; tpd_limit: number | null; key_id: number | null;
  } | undefined;
  if (!m) return false;

  const limits = { rpm: m.rpm_limit, rpd: m.rpd_limit, tpm: m.tpm_limit, tpd: m.tpd_limit };
  const keys = db.prepare(
    "SELECT id, model_scope_json FROM api_keys WHERE platform = ? AND enabled = 1 AND status IN ('healthy', 'unknown')"
  ).all(m.platform) as { id: number; model_scope_json: string | null }[];

  // Keys of the model's own custom endpoint (#212, #619); a key belonging to a
  // DIFFERENT endpoint cannot serve it, so it doesn't count as an alternative.
  const endpointKeyIds = m.platform === 'custom' && m.key_id != null
    ? customEndpointKeyIds(db, m.key_id)
    : null;

  for (const k of keys) {
    if (k.id === excludingKeyId) continue;
    if (endpointKeyIds && !endpointKeyIds.has(k.id)) continue;
    // A sibling scoped away from this model can never serve it (#657) — counting
    // it would wrongly suppress the model-level penalty this gate exists for.
    if (!scopeAllows(parseModelScope(k.model_scope_json), m.model_id)) continue;
    if (skipKeys?.has(`${m.platform}:${m.model_id}:${k.id}`)) continue;
    if (isOnCooldown(m.platform, m.model_id, k.id)) continue;
    if (!canUseProvider(m.platform, k.id)) continue;
    if (!canUseProviderMinute(m.platform, k.id)) continue;
    if (!canMakeRequest(m.platform, m.model_id, k.id, limits)) continue;
    // A per-minute token spike on the failed key doesn't mean a fresh key lacks
    // headroom; a nominal 1-token probe only rules out a key already at its
    // TPM/TPD ceiling.
    if (!canUseTokens(m.platform, m.model_id, k.id, 1, limits)) continue;
    if (!canUseProviderTokens(m.platform, k.id, m.model_id, 1)) continue;
    return true;
  }
  return false;
}

/**
 * Every key that can be ROUTED to this model: enabled + healthy/unknown, not
 * scoped away from the model (#657), and — for a custom model — belonging to
 * the model's own endpoint (#212, #619). Deliberately ignores the transient
 * gates hasOtherUsableKey applies (cooldown, quotas): the caller here is the
 * model-level bench, which needs the full key set to take a sick model out of
 * rotation, not "who could serve the next request".
 */
export function routableKeyIdsForModel(modelDbId: number): number[] {
  const db = getDb();
  const m = db.prepare(`
    SELECT platform, model_id, rpm_limit, rpd_limit, tpm_limit, tpd_limit, key_id
      FROM models WHERE id = ?
  `).get(modelDbId) as {
    platform: string; model_id: string;
    rpm_limit: number | null; rpd_limit: number | null;
    tpm_limit: number | null; tpd_limit: number | null; key_id: number | null;
  } | undefined;
  if (!m) return [];

  const keys = db.prepare(
    "SELECT id, model_scope_json FROM api_keys WHERE platform = ? AND enabled = 1 AND status IN ('healthy', 'unknown')"
  ).all(m.platform) as { id: number; model_scope_json: string | null }[];

  // Keys of the model's own custom endpoint (#212, #619); a key belonging to a
  // DIFFERENT endpoint cannot serve it, so it doesn't count as an alternative.
  const endpointKeyIds = m.platform === 'custom' && m.key_id != null
    ? customEndpointKeyIds(db, m.key_id)
    : null;

  return keys
    .filter(k => {
      // Skip keys of other models' custom endpoints
      if (endpointKeyIds && !endpointKeyIds.has(k.id)) return false;
      // Skip keys scoped away from this model's model_id
      if (!scopeAllows(parseModelScope(k.model_scope_json), m.model_id)) return false;
      return true;
    })
    .map(k => k.id);
}

/**
 * Whether the model has ANY usable key right now (ignoring per-key cooldowns
 * from *this* request, but respecting global cooldowns and quotas).
 * Used by the retry loops to decide whether to retry the same model after a
 * single key's 429/402/5xx/timeout.
 */
export function hasAnyUsableKey(modelDbId: number, skipKeys?: Set<string>): boolean {
  return routableKeyIdsForModel(modelDbId).some(keyId => !skipKeys?.has(`${getModelPlatform(modelDbId)}:${getModelModelId(modelDbId)}:${keyId}`));
}

/**
 * Get the platform string for a model (e.g., 'openai', 'ollama').
 */
function getModelPlatform(modelDbId: number): string {
  const db = getDb();
  const m = db.prepare(`
    SELECT platform FROM models WHERE id = ?
  `).get(modelDbId) as { platform: string } | undefined;
  return m?.platform ?? '';
}

/**
 * Get the model_id string for a model (e.g., 'gpt-4-turbo').
 */
function getModelModelId(modelDbId: number): string {
  const db = getDb();
  const m = db.prepare(`
    SELECT model_id FROM models WHERE id = ?
  `).get(modelDbId) as { model_id: string } | undefined;
  return m?.model_id ?? '';
}

/**
 * Route a request to the best available model.
 *
 * Ordering depends on the configured strategy (see orderChain). Everything
 * downstream — key round-robin, cooldowns, token pre-checks, custom base_url
 * resolution, vision filtering, sticky sessions — is strategy-independent.
 *
 * If preferredModelDbId is set, that model gets tried FIRST (sticky sessions).
 * This prevents hallucination from model switching mid-conversation.
 *
 * @param estimatedTokens - estimated total tokens for rate limit check
 * @param skipKeys - set of "platform:modelId:keyId" to skip (failed on this request)
 * @param preferredModelDbId - try this model first (sticky session)
 * @param requireVision - only consider models that accept image input (#118)
 * @param requireTools - only consider models that emit structured tool_calls
 * @param skipPlatforms - platforms ruled out for the rest of this request (#788)
 */
export function routeRequest(
  estimatedTokens: number | null | undefined,
  skipKeys?: Set<string> | undefined,
  preferredModelDbId: number | null | undefined,
  requireVision: boolean = false,
  requireTools: boolean = false,
  skipPlatforms?: Set<string> | undefined
): ResolvedChain | null {
  const db = getDb();
  const strategy = getRoutingStrategy();
  refreshStatsCache(db);

  const chain = getActiveChain(db);

  // For display we score under 'balanced' weights when in priority mode, so the
  // table still shows a meaningful ranking even with the bandit turned off.
  const weights = weightsFor(strategy) ?? BANDIT_PRESETS.balanced;
  const composites = chain.map(e => intelligenceComposite(e.size_label, e.intelligence_rank));
  const intelMin = composites.length ? Math.min(...composites) : 0;
  const intelMax = composites.length ? Math.max(...composites) : 0;
  const keyCounts = usableKeyCountsByPlatform(db);
  const headroomCfg = getHeadroomThresholds();

  const scores: RoutingScore[] = chain.map(entry => {
    const scored = scoreChainEntry(entry, weights, intelMin, intelMax, false, keyCounts, headroomCfg);
    return { entry, score: scored.score };
  });

  // Sort by tier first (S > A > B), then by score descending, then by priority ascending
  const ordered = scores
    .sort((a, b) => tier(a.entry) - tier(b.entry) || b.score - a.score || a.entry.priority - b.entry.priority);

  // Apply sticky session preference if set
  if (preferredModelDbId !== null) {
    const stickyIndex = ordered.findIndex(e => e.entry.model_db_id === preferredModelDbId);
    if (stickyIndex !== -1) {
      // Move the preferred model to the front
      const [sticky] = ordered.splice(stickyIndex, 1);
      ordered.unshift(sticky);
    }
  }

  // Filter out models that don't meet vision/tool requirements
  const filtered = ordered.filter(e => {
    if (requireVision && !e.entry.supports_vision) return false;
    if (requireTools && !e.entry.supports_tools) return false;
    return true;
  });

  // Filter out platforms that are skipped
  const platformFiltered = filtered.filter(e => {
    if (skipPlatforms && skipPlatforms.has(e.entry.platform)) return false;
    return true;
  });

  // Find the first model that has a usable key
  for (const { entry, score } of platformFiltered) {
    // Check if this model has any usable key (respecting our KeyPoolManager cooldowns)
    const keyPool = KeyPoolManager.getInstance(entry.platform as Platform);
    const allKeys = db.prepare(
      "SELECT * FROM api_keys WHERE platform = ? AND enabled = 1 AND status IN ('healthy', 'unknown')"
    ).all(entry.platform) as KeyRow[];
    const keys = allKeys.filter(k => scopeAllows(parseModelScope(k.model_scope_json), entry.model_id));

    // For custom models, restrict to keys belonging to the model's endpoint
    const endpointKeyIds = entry.platform === 'custom' && entry.key_id != null
      ? customEndpointKeyIds(db, entry.key_id)
      : null;
    if (endpointKeyIds) {
      const filteredKeys = keys.filter(k => endpointKeyIds.has(k.id));
      if (filteredKeys.length === 0) continue;
      keys = filteredKeys;
    }

    // Check if any key is available in our KeyPoolManager
    const hasAvailableKey = keys.some(key => keyPool.isKeyAvailable(key.id));
    if (hasAvailableKey) {
      // Build the chain for this model (just this model for now)
      const chain: ChainRow[] = [entry];
      return { chain, strategyKey: getRoutingStrategy() };
    }
  }

  // No usable key found for any model
  return null;
}

/**
 * Get the routing weights for a given strategy.
 * Returns the weight vector for the strategy, or null if not found.
 */
function weightsFor(strategy: RoutingStrategy): RoutingWeights | null {
  switch (strategy) {
    case 'priority':
      return null; // Special case: handled by orderChain
    case 'balanced':
      return BANDIT_PRESETS.balanced;
    case 'smartest':
      return BANDIT_PRESETS.smartest;
    case 'fastest':
      return BANDIT_PRESETS.fastest;
    case 'reliable':
      return BANDIT_PRESETS.reliable;
    case 'custom':
      return getCustomWeights();
    default:
      return null;
  }
}

/**
 * Get the custom weights from settings.
 * Returns a weight vector normalized to sum 1.
 */
function getCustomWeights(): RoutingWeights {
  const db = getDb();
  const reliability = getSetting('custom_weight_reliability') ?? 0.33;
  const speed = getSetting('custom_weight_speed') ?? 0.33;
  const intelligence = getSetting('custom_weight_intelligence') ?? 0.34;

  // Normalize to sum 1
  const total = reliability + speed + intelligence;
  return {
    reliability: reliability / total,
    speed: speed / total,
    intelligence: intelligence / total
  };
}

/**
 * Get the active chain (either from a profile or fallback_config).
 */
function getActiveChain(db: Db): ChainRow[] {
  const profileId = getActiveProfileId(db);
  if (profileId != null) {
    return db.prepare(`
      SELECT pm.model_db_id, pm.priority, pm.enabled,
             m.platform, m.model_id, m.display_name, m.intelligence_rank,
             m.size_label, m.monthly_token_budget,
             m.rpm_limit, m.rpd_limit, m.tpm_limit, m.tpd_limit, m.supports_vision,
             m.supports_tools, m.context_window, m.key_id, m.endpoint_scope
      FROM profile_models pm
      JOIN models m ON m.id = pm.model_db_id AND m.enabled = 1
      WHERE pm.profile_id = ?
      ORDER BY pm.priority ASC
    `).all(profileId) as ChainRow[];
  }

  return db.prepare(`
    SELECT fc.model_db_id, fc.priority, fc.enabled,
           m.platform, m.model_id, m.display_name, m.intelligence_rank,
           m.size_label, m.monthly_token_budget,
           m.rpm_limit, m.rpd_limit, m.tpm_limit, m.tpd_limit, m.supports_vision,
           m.supports_tools, m.context_window, m.key_id, m.endpoint_scope
    FROM fallback_config fc
    JOIN models m ON m.id = fc.model_db_id AND m.enabled = 1
    ORDER BY fc.priority ASC
  `).all() as ChainRow[];
}

/**
 * Get the active profile ID.
 */
function getActiveProfileId(db: Db): number | null {
  const setting = getSetting('active_profile_id');
  return setting !== null ? parseInt(setting, 10) : null;
}

/**
 * Check if quota weighting applies to this model (has data and multiple keys).
 */
function quotaWeightingApplies(entry: ChainRow): boolean {
  return entry.tpm_limit != null && entry.tpd_limit != null;
}

/**
 * Get the model stats key for scoring/ordering.
 */
function modelStatsKey(platform: Platform, model_id: string, endpoint_scope: string | null): string {
  return `model_stats:${platform}:${model_id}:${endpoint_scope ?? ''}`;
}

/**
 * Get the soonest cooldown expiry for a platform/model/key.
 */
function getSoonestCooldownExpiry(platform: Platform, model_id: string, key_id: number): number | null {
  const db = getDb();
  const row = db.prepare(`
    SELECT expiry_ts FROM key_cooldowns
    WHERE platform = ? AND model_id = ? AND key_id = ?
    ORDER BY expiry_ts ASC
    LIMIT 1
  `).get(platform, model_id, key_id) as { expiry_ts: number } | undefined;
  return row?.expiry_ts ?? null;
}

/**
 * Check if a key is on cooldown.
 */
function isOnCooldown(platform: Platform, model_id: string, key_id: number): boolean {
  const expiry = getSoonestCooldownExpiry(platform, model_id, key_id);
  return expiry !== null && expiry > Date.now();
}

/**
 * Get usable key counts by platform for scoring.
 */
function usableKeyCountsByPlatform(db: Db): Record<Platform, number> {
  const counts: Record<Platform, number> = {};
  const rows = db.prepare(`
    SELECT platform, COUNT(*) as count
    FROM api_keys
    WHERE enabled = 1 AND status IN ('healthy', 'unknown')
    GROUP BY platform
  `).all() as { platform: Platform; count: number }[];

  for (const row of rows) {
    counts[row.platform] = row.count;
  }
  return counts;
}

/**
 * Order keys by score (reliability/speed/intelligence).
 * Returns null if no scoring data is available.
 */
function orderKeysByScore(entry: ChainRow, keys: KeyRow[]): KeyRow[] | null {
  const db = getDb();
  if (getRoutingStrategy() === 'priority') {
    return null; // Use original order for priority strategy
  }

  refreshStatsCache(db);

  // Scoped so two relays offering the same model id don't share one rotation
  // cursor over the platform's key list (#651).
  const rrKey = modelStatsKey(entry.platform, entry.model_id, entry.endpoint_scope);

  // Get the score for each key
  const scoredKeys = keys.map(key => {
    const stats = getScoreCache(db, rrKey, key.id);
    return { key, score: stats?.score ?? 0 };
  });

  // Sort by score descending
  const sorted = scoredKeys.sort((a, b) => b.score - a.score);

  // Return just the keys in score order
  return sorted.map(({ key }) => key);
}

/**
 * Order keys by remaining quota (for quota weighting).
 * Returns keys ordered by remaining quota descending.
 */
function orderKeysByRemainingQuota(entry: ChainRow, keys: KeyRow[]): KeyRow[] {
  const limits = {
    rpm: entry.rpm_limit,
    rpd: entry.rpd_limit,
    tpm: entry.tpm_limit,
    tpd: entry.tpd_limit,
  };

  // Get the used quota for each key
  const keysWithQuota = keys.map(key => {
    const usedRpm = getModelWindowUsedFraction(db, entry.platform, entry.model_id, key.id, 'rpm');
    const usedRpd = getModelWindowUsedFraction(db, entry.platform, entry.model_id, key.id, 'rpd');
    const usedTpm = getModelWindowUsedFraction(db, entry.platform, entry.model_id, key.id, 'tpm');
    const usedTpd = getModelWindowUsedFraction(db, entry.platform, entry.model_id, key.id, 'tpd');

    // Calculate remaining quota (0-1, where 1 is full quota remaining)
    const remainingRpm = limits.rpm !== null ? 1 - usedRpm : 1;
    const remainingRpd = limits.rpd !== null ? 1 - usedRpd : 1;
    const remainingTpm = limits.tpm !== null ? 1 - usedTpm : 1;
    const remainingTpd = limits.tpd !== null ? 1 - usedTpd : 1;

    // Use the minimum remaining quota as the bottleneck
    const remainingQuota = Math.min(
      remainingRpm,
      remainingRpd,
      remainingTpm,
      remainingTpd
    );

    return { key, remainingQuota };
  });

  // Sort by remaining quota descending
  const sorted = keysWithQuota.sort((a, b) => b.remainingQuota - a.remainingQuota);

  // Return just the keys in quota order
  return sorted.map(({ key }) => key);
}

/**
 * Get the score cache entry for a key.
 */
function getScoreCache(db: Db, rrKey: string, keyId: number): ScoreCacheEntry | null {
  const row = db.prepare(`
    SELECT score, updated_at FROM score_cache
    WHERE rr_key = ? AND key_id = ?
  `).get(rrKey, keyId) as { score: number; updated_at: number } | undefined;

  if (!row) return null;

  // Check if cache is stale (older than 60 seconds)
  const now = Date.now();
  if (now - row.updated_at > 60 * 1000) {
    return null;
  }

  return { score: row.score };
}

/**
 * Refresh the stats cache (no-op if fresh, cheap if stale).
 */
function refreshStatsCache(db: Db): void {
  // Implementation would go here - for now it's a no-op
  // In the real implementation, this would update the score_cache table
  // with aggregated reliability/speed data from the model_stats table
}

/**
 * Get the model window used fraction for a specific limit type.
 */
function getModelWindowUsedFraction(db: Db, platform: Platform, model_id: string, key_id: number, type: 'rpm' | 'rpd' | 'tpm' | 'tpd'): number {
  // Implementation would go here - for now return 0 (no usage)
  // In the real implementation, this would calculate the fraction of
  // the window that has been used based on the rate limit windows
  return 0;
}

/**
 * Score a chain entry for routing.
 */
function scoreChainEntry(
  entry: ChainRow,
  weights: RoutingWeights,
  intelMin: number,
  intelMax: number,
  sampled: boolean,
  keyCounts: Record<Platform, number>,
  headroomCfg: HeadroomThresholds
): ScoredChainEntry {
  const db = getDb();

  // Calculate intelligence composite score (normalized 0-1)
  const intelligence = intelligenceComposite(entry.size_label, entry.intelligence_rank);
  const intelligenceScore = (intelligence - intelMin) / (intelMax - intelMin);

  // Get reliability score from cache (or default to 0.5 if no data)
  const rrKey = modelStatsKey(entry.platform, entry.model_id, entry.endpoint_scope);
  const reliability = getScoreCache(db, rrKey, 0)?.score ?? 0.5; // 0 is a dummy key_id for model-level

  // Get speed score from cache (or default to 0.5 if no data)
  const speed = getScoreCache(db, rrKey, 0)?.score ?? 0.5;

  // Calculate headroom factor (how much room before hitting rate limits)
  const headroom = headroomFactor(entry, keyCounts, headroomCfg);

  // Calculate rate limit factor (how close we are to rate limits)
  const rateLimit = rateLimitFactor(entry, keyCounts);

  // Combine the scores
  const rawScore = combineScore({
    reliability,
    speed,
    intelligence: intelligenceScore,
    headroom,
    rateLimit
  }, weights);

  // Apply exploration bonus if we haven't sampled this model much
  const exploreBoost = sampled ? 0 : 0.1;

  // Final score
  const finalScore = Math.min(1, rawScore + exploreBoost);

  return { entry, score: finalScore };
}

/**
 * Combine multiple scores into a single score using weights.
 */
function combineScore(scores: { reliability: number; speed: number; intelligence: number; headroom: number; rateLimit: number }, weights: RoutingWeights): number {
  return (
    scores.reliability * weights.reliability +
    scores.speed * weights.speed +
    scores.intelligence * weights.intelligence +
    scores.headroom * weights.headroom +
    scores.rateLimit * weights.rateLimit
  );
}

/**
 * Calculate the intelligence composite score from size_label and intelligence_rank.
 */
function intelligenceComposite(sizeLabel: string, intelligenceRank: number): number {
  // Simplified implementation - in reality this would be more complex
  // For now, just normalize the intelligence rank (lower is better)
  // Size label is not used in this simplified version
  return 1 - (intelligenceRank / 1000); // Assuming max rank of 1000
}

/**
 * Calculate the headroom factor (how much room before hitting rate limits).
 */
function headroomFactor(entry: ChainRow, keyCounts: Record<Platform, number>, headroomCfg: HeadroomThresholds): number {
  // Simplified implementation
  // In reality, this would check how close we are to various rate limits
  return 0.5; // Neutral value
}

/**
 * Calculate the rate limit factor (how close we are to rate limits).
 */
function rateLimitFactor(entry: ChainRow, keyCounts: Record<Platform, number>): number {
  // Simplified implementation
  // In reality, this would check how close we are to RPM/RPD/TPM/TPD limits
  return 0.5; // Neutral value
}

/**
 * Get the peak hours configuration.
 */
function getPeakHoursConfig(): PeakHoursConfig {
  const db = getDb();
  const startHour = getSetting('peak_hours_start_hour') ?? 9;
  const endHour = getSetting('peak_hours_end_hour') ?? 17;
  const timezone = getSetting('peak_hours_timezone') ?? 'UTC';
  const enabled = getSetting('peak_hours_enabled') === 'true';

  return {
    startHour: parseInt(startHour, 10),
    endHour: parseInt(endHour, 10),
    timezone,
    enabled
  };
}

/**
 * Check if the current time is within peak hours.
 */
function isValidPeakHour(now: number = Date.now()): boolean {
  const config = getPeakHoursConfig();
  if (!config.enabled) return false;

  const date = new Date(now);
  const hours = date.getUTCHours(); // Using UTC for simplicity

  // Handle overnight periods (e.g., 22 to 6)
  if (config.startHour <= config.endHour) {
    return hours >= config.startHour && hours < config.endHour;
  } else {
    return hours >= config.startHour || hours < config.endHour;
  }
}

/**
 * Validate that a timezone string is a valid IANA timezone.
 */
function isValidTimezone(timezone: string): boolean {
  // Simplified validation - in reality this would check against the IANA timezone database
  return timezone.length > 0 && timezone.length < 100;
}

/**
 * Get the headroom thresholds configuration.
 */
function getHeadroomThresholds(): HeadroomThresholds {
  const db = getDb();
  // Use default values for now
  return {
    reliability: 0.2,
    speed: 0.2,
    intelligence: 0.2,
    headroom: 0.2,
    rateLimit: 0.2
  };
}

/**
 * Get the default peak hours configuration.
 */
const DEFAULT_PEAK_HOURS: PeakHoursConfig = {
  startHour: 9,
  endHour: 17,
  timezone: 'UTC',
  enabled: false
};

/**
 * Observed speed rank (for scoring).
 * In a real implementation, this would be updated based on actual performance.
 */
const OBSERVED_SPEED_RANK: number = 50;

/**
 * Timeout latency cap in milliseconds.
 * Requests exceeding this latency will be considered timeouts.
 */
const TIMEOUT_LATENCY_CAP_MS: number = 30000; // 30 seconds

// Initialize the PENALTY_PER_FAIL constant
const PENALTY_PER_FAIL: number = 0.1;"}

