    return null;
  }
  const provider = getProvider(entry.platform as Platform)!;

  // Get all enabled keys for this provider
  const allKeys = db.prepare(
    "SELECT * FROM api_keys WHERE platform = ? AND enabled = 1 AND status IN ('healthy', 'unknown')"
  ).all(entry.platform) as KeyRow[];
  if (allKeys.length === 0) {
    diag?.push(`${label}: no enabled+healthy key for platform`);
    return null;
  }

  // Filter by model scope (scoped keys)
  const keys = allKeys.filter(k => scopeAllows(parseModelScope(k.model_scope_json), entry.model_id));
  if (keys.length === 0) {
    diag?.push(`${label}: no usable key — ${allKeys.length} key(s) scoped to other models`);
    return null;
  }

  // For custom models, restrict to keys belonging to the model's endpoint
  const endpointKeyIds = entry.platform === 'custom' && entry.key_id != null
    ? customEndpointKeyIds(db, entry.key_id)
    : null;
  if (endpointKeyIds) {
    const filteredKeys = keys.filter(k => endpointKeyIds.has(k.id));
    if (filteredKeys.length === 0) {
      diag?.push(`${label}: no usable key — ${keys.length} key(s) not bound to model's endpoint`);
      return null;
    }
    keys = filteredKeys;
  }

  // Refresh stats cache for scoring (if not using priority strategy)
  if (getRoutingStrategy() !== 'priority') {
    refreshStatsCache(db);
  }

