      proxyUrl: decryptProxyUrl(key),
      platform: entry.platform,
      displayName: entry.display_name,
      endpointScope: entry.endpoint_scope ?? '',
      rpdLimit: limits.rpd,
      tpdLimit: limits.tpd,
      release: () => releaseLease(leaseId);
    };
