 * DeepSeek Harness Integration
 * Provides tracing and fallback capabilities using DeepSeek Harness
 */

import { execSync } from 'child_process';
import { getLogger } from '../lib/logger';

const logger = getLogger('deepseek-harness');

/**
 * Execute a DeepSeek Harness command
 * @param command - The command to execute (e.g., 'chat', 'complete')
 * @param args - Arguments for the command
 * @returns The output from DeepSeek Harness
 */
export function executeDeepSeekHarness(command: string, args: Record<string, any>): any {
  try {
    const argString = Object.entries(args)
      .map(([key, value]) => {
        if (typeof value === 'string') {
          return `--${key} "${value}"`;
        } else if (typeof value === 'boolean') {
          return value ? `--${key}` : '';
        } else {
          return `--${key} ${JSON.stringify(value)}`;
        }
      })
      .filter(Boolean)
      .join(' ');

    const fullCommand = `dsh ${command} ${argString}`;
    logger.info(`Executing DeepSeek Harness: ${fullCommand}`);

    const output = execSync(fullCommand, {
      encoding: 'utf8',
      timeout: 30000, // 30 seconds timeout
    });

    try {
      return JSON.parse(output);
    } catch (e) {
      return output;
    }
  } catch (error) {
    logger.error(`DeepSeek Harness error: ${error.message}`);
    throw new Error(`DeepSeek Harness failed: ${error.message}`);
  }
}

/**
 * Trace a request using DeepSeek Harness
 * @param model - The model used
 * @param input - The input to the model
 * @param output - The output from the model
 * @param metadata - Additional metadata
 */
export function traceWithDeepSeekHarness(
  model: string,
  input: any,
  output: any,
  metadata: Record<string, any> = {}
): void {
  try {
    executeDeepSeekHarness('trace', {
      model,
      input: JSON.stringify(input),
      output: JSON.stringify(output),
