        displayName: 'DeepSeek Harness (Fallback)',
        endpointScope: '',
        rpdLimit: 0,
        tpdLimit: 0,
        release: () => {},
      };
    }
  } catch (error) {
    // DeepSeek Harness fallback failed, throw the original error
  }

  throw new RouteError(summarizeExhaustion(diag, getSoonestCooldownExpiry()), 429, diag);
