{"content": "import { Router } from 'express';
import type { Request, Response } from 'express';
import { getDb } from '../db/index.js';

export const routingHistoryRouter = Router();

/**
 * GET /routing/history
 * Returns the routing history for the last N hours
 * Shows which models were tried, their scores, and success/failure
 */
routingHistoryRouter.get('/history', (req: Request, res: Response) => {
  try {
    const db = getDb();
    const hours = parseInt(req.query.hours as string) || 24;
    const since = new Date(Date.now() - hours * 60 * 60 * 1000).toISOString();

    // Query the requests table for routing history
    const history = db.prepare(`
      SELECT
        r.id,
        r.created_at,
        r.platform,
        r.model_id,
        r.key_id,
        r.status,
        r.latency_ms,
        r.input_tokens,
        r.output_tokens,
        k.label as key_label
      FROM requests r
      LEFT JOIN api_keys k ON r.key_id = k.id
      WHERE r.created_at >= ?
      ORDER BY r.created_at DESC
      LIMIT 1000
    `).all(since);

    // Format the history for the frontend
    const formatted = history.map((row: any) => ({
      timestamp: new Date(row.created_at).getTime(),
      modelId: row.model_id,
      platform: row.platform,
      keyId: row.key_id,
      keyLabel: row.key_label,
      status: row.status,
      latencyMs: row.latency_ms,
      inputTokens: row.input_tokens,
      outputTokens: row.output_tokens,
      success: row.status === 'success',
    }));

    res.json({ history: formatted });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/**
 * GET /routing/traces
 * Returns recent traces for debugging
 * Shows the full routing decision path
 */
routingHistoryRouter.get('/traces', (req: Request, res: Response) => {
  try {
    const db = getDb();
    const limit = parseInt(req.query.limit as string) || 100;

    // Query recent requests with full details
    const traces = db.prepare(`
      SELECT
        r.id,
        r.created_at,
        r.platform,
        r.model_id,
        r.key_id,
        r.status,
        r.error_type,
        r.error_message,
        r.latency_ms,
        r.input_tokens,
        r.output_tokens,
        k.label as key_label
      FROM requests r
      LEFT JOIN api_keys k ON r.key_id = k.id
      ORDER BY r.created_at DESC
      LIMIT ?
    `).all(limit);

    res.json({ traces });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

/**
 * GET /routing/score-history
 * Returns score changes over time for specific models
 */
routingHistoryRouter.get('/score-history', (req: Request, res: Response) => {
  try {
    const db = getDb();
    const modelId = req.query.modelId as string;
    const platform = req.query.platform as string;
    const days = parseInt(req.query.days as string) || 7;

    if (!modelId || !platform) {
      return res.status(400).json({ error: 'modelId and platform required' });
    }

    const since = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString();

    // Get daily aggregated stats
    const stats = db.prepare(`
      SELECT
        date(created_at) as date,
        COUNT(*) as total,
        SUM(CASE WHEN status = 'success' THEN 1 ELSE 0 END) as successes,
        SUM(CASE WHEN status = 'error' THEN 1 ELSE 0 END) as failures,
        AVG(latency_ms) as avg_latency,
        SUM(input_tokens + output_tokens) as total_tokens
      FROM requests
      WHERE platform = ? AND model_id = ? AND created_at >= ?
      GROUP BY date(created_at)
      ORDER BY date ASC
    `).all(platform, modelId, since);

    res.json({ history: stats });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});
