import type { Request, Response } from 'express';
import { getDb } from '../db/index.js';
import { getRoutingScores } from '../services/router.js';

export const sseRouter = Router();

/**
 * Server-Sent Events for real-time analytics
 * Streams routing scores, model stats, and traces
 */
const clients = new Set<Response>();

// Broadcast function for other parts of the app to send updates
export function broadcastSSE(event: string, data: any) {
  const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
  clients.forEach((client) => {
    try {
      client.write(message);
    } catch (err) {
      clients.delete(client);
    }
  });
}

/**
 * GET /sse/analytics
 * Streams routing analytics updates
 */
sseRouter.get('/analytics', (req: Request, res: Response) => {
  // SSE headers
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no');

  // Add client to set
  clients.add(res);

  // Send initial data
  try {
    const scores = getRoutingScores();
    res.write(`event: scores\ndata: ${JSON.stringify(scores)}\n\n`);
  } catch (err) {
    // Silent fail
  }

  // Send periodic updates every 5 seconds
  const interval = setInterval(() => {
    try {
      const scores = getRoutingScores();
      res.write(`event: scores\ndata: ${JSON.stringify(scores)}\n\n`);
    } catch (err) {
      // Silent fail
    }
  }, 5000);

  // Heartbeat every 30s
  const heartbeat = setInterval(() => {
    try {
      res.write(`: heartbeat\n\n`);
    } catch (err) {
      // Silent fail
    }
  }, 30000);

  // Cleanup on disconnect
  req.on('close', () => {
    clearInterval(interval);
    clearInterval(heartbeat);
    clients.delete(res);
    res.end();
  });
});

