{"content": "import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';

/**
 * Smart Real-Time Store
 * Only subscribes to data that's currently visible
 * Uses SSE for real-time updates with automatic reconnection
 */

export interface RoutingScore {
  modelDbId: number;
  platform: string;
  modelId: string;
  displayName: string;
  enabled: boolean;
  reliability: number;
  speed: number;
  intelligence: number;
  headroom: number;
  rateLimit: number;
  score: number;
  totalRequests: number;
}

export interface ModelRequest {
  id: number;
  created_at: string;
  platform: string;
  model_id: string;
  status: string;
  latency_ms: number;
  input_tokens: number;
  output_tokens: number;
}

export interface Trace {
  id: number;
  created_at: string;
  platform: string;
  model_id: string;
  status: string;
  error_type?: string;
  latency_ms: number;
}

interface RealtimeState {
  // Visibility flags - what user is currently looking at
  visible: {
    scores: boolean;
    models: boolean;
    traces: boolean;
  };

  // Data stores
  scores: RoutingScore[];
  requests: ModelRequest[];
  traces: Trace[];

  // Connection state
  connected: {
    scores: boolean;
    models: boolean;
    traces: boolean;
  };

  // Actions
  setVisible: (key: 'scores' | 'models' | 'traces', visible: boolean) => void;
  setScores: (scores: RoutingScore[]) => void;
  setRequests: (requests: ModelRequest[]) => void;
  setTraces: (traces: Trace[]) => void;
  setConnected: (key: 'scores' | 'models' | 'traces', connected: boolean) => void;
}

/**
 * SSE Connection Manager
 * Manages EventSource connections based on visibility
 * Only opens connections for visible data
 */
class SSEConnectionManager {
  private connections: Map<string, EventSource> = new Map();
  private reconnectAttempts: Map<string, number> = new Map();
  private maxReconnectAttempts = 5;
  private reconnectDelay = 1000;

  /**
   * Open SSE connection if not already open
   */
  connect(key: string, url: string, onMessage: (data: any) => void, onStatus: (connected: boolean) => void) {
    if (this.connections.has(key)) {
      return; // Already connected
    }

    try {
      const eventSource = new EventSource(url, { withCredentials: true });

      eventSource.addEventListener('open', () => {
        this.reconnectAttempts.set(key, 0);
        onStatus(true);
      });

      eventSource.addEventListener('error', () => {
        onStatus(false);
        this.handleReconnect(key, url, onMessage, onStatus);
      });

      // Listen for specific events
      eventSource.addEventListener('scores', (e: MessageEvent) => {
        try {
          const data = JSON.parse(e.data);
          onMessage(data);
        } catch (err) {
          // Silent fail
        }
      });

      eventSource.addEventListener('requests', (e: MessageEvent) => {
        try {
          const data = JSON.parse(e.data);
          onMessage(data);
        } catch (err) {
          // Silent fail
        }
      });

      eventSource.addEventListener('traces', (e: MessageEvent) => {
        try {
          const data = JSON.parse(e.data);
          onMessage(data);
        } catch (err) {
          // Silent fail
        }
      });

      this.connections.set(key, eventSource);
    } catch (err) {
      onStatus(false);
    }
  }

  /**
   * Close SSE connection
   */
  disconnect(key: string) {
    const conn = this.connections.get(key);
    if (conn) {
      conn.close();
      this.connections.delete(key);
      this.reconnectAttempts.delete(key);
    }
  }

  /**
   * Handle reconnection with exponential backoff
   */
  private handleReconnect(key: string, url: string, onMessage: (data: any) => void, onStatus: (connected: boolean) => void) {
    const attempts = this.reconnectAttempts.get(key) || 0;

    if (attempts >= this.maxReconnectAttempts) {
      return;
    }

    this.reconnectAttempts.set(key, attempts + 1);
    this.disconnect(key);

    setTimeout(() => {
      this.connect(key, url, onMessage, onStatus);
    }, this.reconnectDelay * Math.pow(2, attempts));
  }

  /**
   * Close all connections
   */
  disconnectAll() {
    this.connections.forEach((conn, key) => {
      conn.close();
    });
    this.connections.clear();
    this.reconnectAttempts.clear();
  }
}

const sseManager = new SSEConnectionManager();

/**
 * Main real-time store
 * Uses subscribeWithSelector for fine-grained subscriptions
 */
export const useRealtimeStore = create<RealtimeState>()(
  subscribeWithSelector((set, get) => ({
    visible: {
      scores: false,
      models: false,
      traces: false,
    },

    scores: [],
    requests: [],
    traces: [],

    connected: {
      scores: false,
      models: false,
      traces: false,
    },

    setVisible: (key, visible) => {
      set((state) => ({
        visible: { ...state.visible, [key]: visible },
      }));

      // Open or close SSE connection based on visibility
      const state = get();

      if (visible) {
        // Open connection
        if (key === 'scores' && !state.connected.scores) {
          sseManager.connect(
            'scores',
            '/api/sse/analytics',
            (data) => {
              if (data.scores) {
                set({ scores: data.scores });
              }
            },
            (connected) => {
              set((state) => ({
                connected: { ...state.connected, scores: connected },
              }));
            }
          );
        }

        if (key === 'models' && !state.connected.models) {
          sseManager.connect(
            'models',
            '/api/sse/models',
            (data) => {
              if (Array.isArray(data)) {
                set({ requests: data });
              }
            },
            (connected) => {
              set((state) => ({
                connected: { ...state.connected, models: connected },
              }));
            }
          );
        }

        if (key === 'traces' && !state.connected.traces) {
          sseManager.connect(
            'traces',
            '/api/sse/traces',
            (data) => {
              if (Array.isArray(data)) {
                set({ traces: data });
              }
            },
            (connected) => {
              set((state) => ({
                connected: { ...state.connected, traces: connected },
              }));
            }
          );
        }
      } else {
        // Close connection
        if (key === 'scores' && state.connected.scores) {
          sseManager.disconnect('scores');
          set((state) => ({
            connected: { ...state.connected, scores: false },
          }));
        }

        if (key === 'models' && state.connected.models) {
          sseManager.disconnect('models');
          set((state) => ({
            connected: { ...state.connected, models: false },
          }));
        }

        if (key === 'traces' && state.connected.traces) {
          sseManager.disconnect('traces');
          set((state) => ({
            connected: { ...state.connected, traces: false },
          }));
        }
      }
    },

    setScores: (scores) => set({ scores }),
    setRequests: (requests) => set({ requests }),
    setTraces: (traces) => set({ traces }),
    setConnected: (key, connected) =>
      set((state) => ({
        connected: { ...state.connected, [key]: connected },
      })),
  }))
);

/**
 * Hook to automatically manage SSE connection based on visibility
 * Use this in components to auto-subscribe/unsubscribe
 */
export function useRealtimeSubscription(key: 'scores' | 'models' | 'traces') {
  const setVisible = useRealtimeStore((state) => state.setVisible);
  const connected = useRealtimeStore((state) => state.connected[key]);

  // Subscribe when component mounts, unsubscribe when unmounts
  if (typeof window !== 'undefined') {
    // Use useEffect-like pattern manually
    setVisible(key, true);

    // Cleanup function
    return () => {
      setVisible(key, false);
    };
  }

  return () => {
    setVisible(key, false);
  };
}
