{"content":"// Package service provides the application business logic that both gRPC
// and HTTP handlers call. This avoids duplication and keeps the core
// logic in one place.
package service

import (
	"context"
	"encoding/json"
	"time"

	"github.com/ji-podhead/jimesh/server-go/internal/keypool"
	"github.com/ji-podhead/jimesh/server-go/internal/router"
	"github.com/ji-podhead/jimesh/server-go/internal/store"
	pb "github.com/ji-podhead/jimesh/server-go/protos/jimesh"
)

// Service aggregates all subsystem clients.
type Service struct {
	Store    *store.DB
	Router   *router.Store
	KeyPool  *keypool.Pool
	Streams  *streams.Hub // for publishing events
}

// New creates a service with wired dependencies.
func New(db *store.DB, rp *router.Store, kp *keypool.Pool, str *streams.Hub) *Service {
	return &Service{
		Store:    db,
		Router:   rp,
		KeyPool:  kp,
		Streams:  str,
	}
}

// ---------- Models ----------

func (s *Service) ListModels(ctx context.Context, tier string, enabledOnly bool) ([]*pb.Model, error) {
	rows, err := d.ListModels(tier, enabledOnly)
	if err != nil {
		return nil, err
	}
	out := make([]*pb.Model, len(rows))
	for i, r := range rows {
		out[i] = &pb.Model{
			Id:           r.ID,
			Platform:     r.Platform,
			DisplayName:  r.DisplayName,
			IntelligenceRank: r.IntRank,
			SpeedRank:    r.SpeedRank,
			ContextWindow: r.ContextWin,
			SupportsVision: r.Vision,
			SupportsTools: r.Tools,
			Enabled:      r.Enabled,
			InputPricePerM: r.InputPerM,
			OutputPricePerM: r.OutputPerM,
			Tier:         pb.Tier(pb.Tier_value[r.Tier]),
		}
	}
	return out, nil
}

// ---------- Chains ----------

func (s *Service) ListChains(ctx context.Context) ([]*pb.Chain, error) {
	rows, err := d.ListChains()
	if err != nil {
		return nil, err
	}
	out := make([]*pb.Chain, len(rows))
	for i, r := range rows {
		ents := make([]*pb.ChainEntry, len(r.Entries))
		for j, e := range r.Entries {
			ents[j] = &pb.ChainEntry{
				ModelId:    e.ModelID,
				Platform:   e.Platform,
				Priority:   e.Priority,
				Enabled:    e.Enabled,
			}
		}
		out[i] = &pb.Chain{
			Id:   r.ID,
			Name: r.Name,
			Tier: pb.Tier(pb.Tier_value[r.Tier]),
			Entries: ents,
		}
	}
	return out, nil
}

func (s *Service) UpsertChain(ctx context.Context, in *pb.Chain) (*pb.Chain, error) {
	c := store.ChainRow{
		ID:   in.Id,
		Name: in.GetName(),
		Tier: strings.ToLower(in.Tier.String()),
	}
	for _, e := range in.Entries {
		c.Entries = append(c.Entries, store.ChainEntryRow{
			ModelID:  e.GetModelId(),
			Platform: e.GetPlatform(),
			Priority: e.GetPriority(),
			Enabled:  e.GetEnabled(),
		})
	}
	if err := d.UpsertChain(c); err != nil {
		return nil, err
	}
	// reload to return authoritative version
	out, err := d.ListChains()
	if err != nil {
		return nil, err
	}
	for _, ch := range out {
		if ch.ID == in.Id {
			return &pb.Chain{
				Id:   ch.ID,
				Name: ch.Name,
				Tier: pb.Tier(pb.Tier_value[ch.Tier]),
				Entries: func() []*pb.ChainEntry {
					out := make([]*pb.ChainEntry, len(ch.Entries))
					for j, e := range ch.Entries {
						out[j] = &pb.ChainEntry{
							ModelId:    e.ModelID,
							Platform:   e.Platform,
							Priority:   e.Priority,
							Enabled:    e.Enabled,
						}
					}
					return out
				}(),
			}, nil
		}
	}
	return nil, fmt.Errorf("chain not found after upsert: %s", in.Id)
}

// ---------- Routing ----------

func (s *Service) Route(ctx context.Context, in *pb.RouteRequest) (*pb.RouteDecision, error) {
	// 1. Determine which chain to use
	var chain store.ChainRow
	var err error
	if in.ChainId != "" {
		chain, err = d.ChainByID(in.ChainId)
		if err != nil {
			return nil, err
		}
	} else if in.Tier != pb.Tier_TIER_UNSPECIFIED {
		tierStr := strings.ToLower(in.Tier.String())
		chain, err = d.ChainByTier(tierStr)
		if err != nil {
			return nil, err
		}
	} else {
		// default chain? maybe first available
		chains, err := d.ListChains()
		if err != nil {
			return nil, err
		}
		if len(chains) == 0 {
			return nil, fmt.Errorf("no chains configured")
		}
		chain = chains[0]
	}
	// 2. Gather candidates from the chain entries
	var cands []router.Candidate
	for _, e := range chain.Entries {
		if !e.Enabled {
			continue
		}
		md, err := d.ModelByIDPlatform(e.ModelID, e.Platform)
		if err != nil {
			continue // skip missing models
		}
		cands = append(cands, router.Candidate{
			ModelID:    e.ModelID,
			Platform:   e.Platform,
			ChainID:    chain.ID,
			Priority:   e.Priority,
			Vision:     md.Vision,
			Tools:      md.Tools,
			InputPerM:  md.InputPerM,
			OutputPerM: md.OutputPerM,
		})
	}
	if len(cands) == 0 {
		return nil, fmt.Errorf("no enabled models in chain")
	}
	// 3. Pick via bandit
	pick, strat := r.Pick(cands)
	if pick == nil {
		return nil, fmt.Errorf("router pick failed")
	}
	// 4. Record decision (for metrics/streams)
	// TODO: publish RouteEvent via streams after call outcome known
	// For now just return the decision
	return &pb.RouteDecision{
		TracerId:   "trace-" + time.Now().Format("20060102150405.000000"),
		ModelId:    pick.ModelID,
		Platform:   pick.Platform,
		Key:        &pb.Key{Id: 1}, // TODO: real key selection from keypool
		Score:      r.PickScore(pick), // need method
		Strategy:   strat,
		Fallbacks:  func() []*pb.ChainEntry {
			out := make([]*pb.ChainEntry, 0)
			// TODO: remaining chain after pick
			return out
		}(),
	}, nil
}

